<?php
require dirname(__DIR__).'/bootstrap.php';
use AranduGo\Auth;use AranduGo\Csrf;use AranduGo\Support;
Auth::requireLogin();Csrf::verify();
function fail(string $message,int $code=422):never{Support::json(['ok'=>false,'error'=>$message],$code);}
function csvRows(string $csv):array{$rows=[];$handle=fopen('php://temp','r+');fwrite($handle,$csv);rewind($handle);$head=fgetcsv($handle);if(!$head)return[];$head=array_map(fn($v)=>strtolower(trim(preg_replace('/^\xEF\xBB\xBF/','',$v))),$head);while(($row=fgetcsv($handle))!==false){$item=[];foreach($head as $i=>$key)$item[$key]=trim((string)($row[$i]??''));if(array_filter($item,fn($v)=>$v!==''))$rows[]=$item;}return $rows;}
function xlsxRows(string $file):array{if(!class_exists(ZipArchive::class))fail('La extensión ZIP es necesaria para leer archivos Excel .xlsx.');$zip=new ZipArchive();if($zip->open($file)!==true)fail('El archivo Excel no es válido.');$shared=[];$xml=$zip->getFromName('xl/sharedStrings.xml');if($xml){$sx=simplexml_load_string($xml);if($sx)foreach($sx->si as $si)$shared[]=(string)$si->t?:implode('',array_map('strval',$si->r??[]));}$sheet=$zip->getFromName('xl/worksheets/sheet1.xml');$zip->close();if(!$sheet)fail('El Excel debe tener datos en la primera hoja.');$sx=simplexml_load_string($sheet);if(!$sx)return[];$out=[];foreach($sx->sheetData->row as $row){$line=[];foreach($row->c as $cell){$ref=(string)$cell['r'];preg_match('/([A-Z]+)/',$ref,$m);$col=0;foreach(str_split($m[1]??'A') as $ch)$col=$col*26+(ord($ch)-64);$type=(string)$cell['t'];$v=(string)$cell->v;$line[$col-1]=$type==='s'?($shared[(int)$v]??''):$v;}if($line){ksort($line);$out[]=array_values($line);}}if(!$out)return[];$head=array_map(fn($v)=>strtolower(trim((string)$v)),array_shift($out));return array_values(array_filter(array_map(function($row)use($head){$item=[];foreach($head as $i=>$key)$item[$key]=trim((string)($row[$i]??''));return $item;},$out),fn($row)=>array_filter($row,fn($v)=>$v!=='')));}
if(empty($_FILES['content'])||$_FILES['content']['error']!==UPLOAD_ERR_OK)fail('No se recibió el archivo.');$file=$_FILES['content'];if($file['size']>10*1024*1024)fail('El archivo supera los 10 MB.');$ext=strtolower(pathinfo((string)$file['name'],PATHINFO_EXTENSION));try{if($ext==='json'){$data=json_decode((string)file_get_contents($file['tmp_name']),true);if(!is_array($data)||empty($data['business'])||!is_array($data['modules']??null))fail('El JSON no contiene una configuración válida.');Support::json(['ok'=>true,'mode'=>'full','data'=>$data]);}$rows=$ext==='csv'?csvRows((string)file_get_contents($file['tmp_name'])):($ext==='xlsx'?xlsxRows($file['tmp_name']):fail('Usá JSON, CSV o Excel .xlsx.'));Support::json(['ok'=>true,'mode'=>'rows','rows'=>$rows]);}catch(Throwable $e){fail($e->getMessage(),500);}
